// src/Modules/Data.lua:1019-1022 -- the spectres are merged into data.minions, so every consumer
// that resolves a minion type by name reaches them without knowing they came from a second file.
// The `limit` stamp that loop also applies is already baked into each entry above, because the
// dumper reads the table AFTER Data.lua has run.
func init() {
	for id, spectre := range Spectres {
		Minions[id] = spectre
	}
}
